(function(root){
const copy=x=>JSON.parse(JSON.stringify(x));
function cartTotal(cart,catalog){let total=0;const rows=Object.entries(cart);if(!rows.length)throw Error('购物车还是空的');for(const[id,q]of rows){if(!Object.hasOwn(catalog,id)||!Number.isInteger(q)||q<1||q>99)throw Error('购物车商品或数量无效');total+=catalog[id].price*q;if(!Number.isSafeInteger(total))throw Error('金额超出范围')}return total}
function checkout(w,cart,pay,id,at,L){cartTotal(cart,L.catalog);if(w.orders?.some(x=>x.checkout===id))return w;let n=w;for(const[item,quantity]of Object.entries(cart))n=L.purchase(n,{id:id+':'+item,item,quantity,pay,at});n.orders=n.orders.map(o=>o.id.startsWith(id+':')?{...o,checkout:id}:o);n.cart={};return n}
function sponsor(w,id,accept,L,at){const n=L.normalize(w),r=n.sponsorRequests?.find(x=>x.id===id);if(!r)throw Error('代付请求不存在');if(r.status!=='pending')return w;if(!accept){r.status='declined';return n}const total=cartTotal(r.cart,L.catalog);if(total!==r.total)throw Error('清单金额变化，请重新发起');const a=copy(L.account(n,r.roleId));if(a.balance<total)throw Error('角色余额不足');a.balance-=total;a.ledger.push({id,at,type:'sponsor',delta:-total,balance:a.balance,note:'购物车代付'});n.accounts[r.roleId]=a;for(const[item,quantity]of Object.entries(r.cart)){n.inventory[item]=(n.inventory[item]||0)+quantity;n.orders.push({id:id+':'+item,item,quantity,total:L.catalog[item].price*quantity,pay:r.roleId,at,checkout:id,sponsor:true})}r.status='paid';for(const[k,q]of Object.entries(r.cart))if(n.cart?.[k]){n.cart[k]=Math.max(0,n.cart[k]-q);if(!n.cart[k])delete n.cart[k]}return n}
function chapters(text){text=String(text).replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').trim();if(!text)throw Error('书籍内容为空');if(text.length>2000000)throw Error('单本最多200万字，请拆分上传');const starts=[...text.matchAll(/^(?:第[零一二三四五六七八九十百千万\d]+[章节回卷].*|chapter\s+\d+.*)$/gim)];if(starts.length){const out=[];if(starts[0].index>0)out.push({title:'前言',text:text.slice(0,starts[0].index)});starts.forEach((m,i)=>out.push({title:m[0].slice(0,100),text:text.slice(m.index,starts[i+1]?.index||text.length)}));return out.flatMap(c=>Array.from({length:Math.ceil(c.text.length/12000)},(_,i)=>({title:c.title+(c.text.length>12000?' · 第'+(i+1)+'部分':''),text:c.text.slice(i*12000,(i+1)*12000)})))}return Array.from({length:Math.ceil(text.length/6000)},(_,i)=>({title:'第 '+(i+1)+' 节',text:text.slice(i*6000,(i+1)*6000)}))}
function validateBackup(b){if(b?.format!=='rose-palais-move'||b.version!==1||!b.data||!Array.isArray(b.data.media)||!Array.isArray(b.data.songs)||!b.data.local||typeof b.data.local!=='object'||Array.isArray(b.data.local))throw Error('不是有效的小手机搬家文件');for(const[k,v]of Object.entries(b.data.local))if(!k.startsWith('palais.')||typeof v!=='string'||k.length>150)throw Error('存档字段无效');for(const row of b.data.media)if(!Array.isArray(row)||typeof row[0]!=='string'||typeof row[1]!=='string'||!/^data:(image\/(png|jpeg|webp|gif)|audio\/[\w.+-]+)[;,]/i.test(row[1]))throw Error('图片或录音素材格式无效');for(const row of b.data.songs)if(!Array.isArray(row)||typeof row[0]!=='string'||typeof row[1]!=='string'||!/^data:(audio\/[\w.+-]+|application\/octet-stream)[;,]/i.test(row[1]))throw Error('歌曲素材格式无效');return b.data}
const api={cartTotal,checkout,sponsor,chapters,validateBackup};root.PalaisUpgrade22=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
